export function evaluate({ inputs, time, seed, state }) {
  const launchSpeed = inputs.launchSpeed;
  const gravity = 9.8;
  const t = time;

  const height = launchSpeed * t - 0.5 * gravity * t * t;
  const velocity = launchSpeed - gravity * t;

  // Scene layout (y down)
  const laneX = 40;
  const laneY = 50;
  const laneW = 560;
  const laneH = 320;

  const axisX = 100;
  const axisY = 340;
  const axisLength = 280;

  // Map height to y coordinate (up positive in physics, down positive on screen)
  // Max height approx for max speed 5 is 5^2 / (2*9.8) = 1.27m. Give room up to 1.5m.
  const scaleY = 180 / 1.5;
  const ballScreenY = axisY - height * scaleY;
  const ballScreenX = axisX + 150;

  const ball = sdk.circle('ball.toss', ballScreenX, ballScreenY, 28, { role: 'output' });
  const ground = sdk.groundMark('ground', axisX, axisY, 80, 'Launch');
  const axis = sdk.axis('axis.height', { x: axisX, y: axisY, length: axisLength, orientation: 'y', min: 0, max: 1.5, ticks: [0, 0.5, 1.0, 1.5], label: 'Height', unit: 'm', role: 'neutral' });
  const panel = sdk.panel({ x: laneX, y: laneY, w: laneW, h: laneH, title: 'Vertical Throw', state: `Time: ${sdk.format(t, 2)} s`, id: 'lane.toss' });

  // Motion arrow (velocity)
  const vArrows = sdk.vector('vec.v', { x: ballScreenX, y: ballScreenY }, { value: velocity, direction: 'up' }, { scale: 8, minLength: 12, label: 'v', role: 'output' });
  // Gravity arrow (constant acceleration down)
  const gArrows = sdk.vector('vec.a', { x: ballScreenX - 30, y: ballScreenY }, { value: gravity, direction: 'down' }, { scale: 8, minLength: 12, label: 'g', role: 'warning' });

  let motionStateText = 'Moving up';
  if (Math.abs(velocity) < 0.05) {
    motionStateText = 'Still for an instant';
  } else if (velocity < 0) {
    motionStateText = 'Moving down';
  }

  const callout = sdk.callout(ballScreenX + 40, ballScreenY - 20, [motionStateText, 'Gravity pulls down'], { id: 'callout.toss', role: 'output' });

  const objects = [panel, axis, ground, ball, ...vArrows, ...gArrows, callout];

  return {
    frame: {
      width: 640,
      height: 420,
      objects,
      readouts: [
        { id: 'motionState', value: motionStateText },
        { id: 'gravityState', value: 'Gravity pulls down' }
      ]
    },
    quantities: {
      launchSpeed,
      gravity,
      velocity,
      height,
      apexTime: launchSpeed / gravity,
      apexHeight: (launchSpeed * launchSpeed) / (2 * gravity)
    }
  };
}
